import { auditFailure } from '@/server/audit';
import { assertSameOrigin, requireActor, requirePermission, revalidateActor } from '@/server/permissions';
import { apiError, json } from '@/server/http';
import { commitSitePackage, readPackageRequest } from '@/server/site-package';
export const runtime = 'nodejs';
export async function POST(request: Request) {
  try {
    assertSameOrigin(request); let actor = await requireActor(request); requirePermission(actor, 'manage');
    const input = await readPackageRequest(request); actor = revalidateActor(actor, 'manage');
    // 读体与包解码各有等待边界，提交回调负责覆盖后一个窗口。
    return json(await auditFailure(actor, 'package.import', () => commitSitePackage(input, Date.now(), actor, () => { actor = revalidateActor(actor, 'manage'); })));
  } catch (e) { return apiError(e); }
}
